#include <cstdint>
#include <cstring>
#include <vector>
#include <string>
#include <memory>
#include <algorithm>
#include <stdexcept>

// HTTP/1.1 chunked transfer encoding parser
// Used in reverse proxy to reassemble chunked responses before forwarding

namespace http {

struct ParseResult {
    bool complete;
    std::string body;
    int status_code;
};

class ChunkAllocator {
private:
    std::vector<std::unique_ptr<char[]>> pools_;
    static constexpr int MAX_TOTAL_BODY = 10 * 1024 * 1024; // 10MB limit

public:
    // Allocate a buffer for reassembled chunks
    // Returns nullptr if allocation would exceed limits
    char* allocate(int current_size, int additional) {
        // Safety check: ensure we don't exceed max body size
        int new_total = current_size + additional;
        if (new_total > MAX_TOTAL_BODY || new_total < 0) {
            return nullptr;
        }
        auto buf = std::make_unique<char[]>(static_cast<size_t>(new_total));
        char* ptr = buf.get();
        pools_.push_back(std::move(buf));
        return ptr;
    }
};

class ChunkedParser {
private:
    ChunkAllocator allocator_;
    char* body_buffer_;
    int body_length_;
    int body_capacity_;
    bool header_parsed_;
    int content_received_;

    // Parse chunk size from hex string
    int parse_chunk_size(const char* hex_str, int len) {
        int result = 0;
        for (int i = 0; i < len; i++) {
            char c = hex_str[i];
            int digit;
            if (c >= '0' && c <= '9') digit = c - '0';
            else if (c >= 'a' && c <= 'f') digit = 10 + (c - 'a');
            else if (c >= 'A' && c <= 'F') digit = 10 + (c - 'A');
            else if (c == '\r' || c == '\n') break;
            else return -1; // invalid

            // Overflow protection for chunk size parsing
            if (result > 0x7FFFFFF) return -1;
            result = (result << 4) | digit;
        }
        return result;
    }

    // Grow the body buffer to accommodate new data
    bool grow_buffer(int needed) {
        if (body_length_ + needed <= body_capacity_) {
            return true; // already have space
        }

        // Calculate new capacity with growth factor
        int new_capacity = body_capacity_;
        while (new_capacity < body_length_ + needed) {
            new_capacity = new_capacity + (new_capacity >> 1) + 64;
            // Check for overflow in capacity calculation
            if (new_capacity < 0) return false;
        }

        char* new_buf = allocator_.allocate(0, new_capacity);
        if (!new_buf) return false;

        if (body_buffer_ && body_length_ > 0) {
            std::memcpy(new_buf, body_buffer_, static_cast<size_t>(body_length_));
        }
        body_buffer_ = new_buf;
        body_capacity_ = new_capacity;
        return true;
    }

    // Append chunk data to body buffer
    bool append_chunk(const char* data, int chunk_len) {
        if (chunk_len <= 0) return chunk_len == 0;
        if (!grow_buffer(chunk_len)) return false;

        std::memcpy(body_buffer_ + body_length_, data, static_cast<size_t>(chunk_len));
        body_length_ += chunk_len;
        return true;
    }

public:
    ChunkedParser() : body_buffer_(nullptr), body_length_(0), 
                      body_capacity_(0), header_parsed_(false),
                      content_received_(0) {}

    // Parse a complete chunked HTTP response
    // Input: raw response bytes after headers
    // The vulnerability is in how multiple chunks interact with the int arithmetic
    ParseResult parse_chunked_body(const char* data, int data_len) {
        ParseResult result{false, "", 200};

        if (!data || data_len <= 0) {
            return result;
        }

        int pos = 0;

        while (pos < data_len) {
            // Find end of chunk size line
            int line_end = -1;
            for (int i = pos; i < data_len - 1; i++) {
                if (data[i] == '\r' && data[i+1] == '\n') {
                    line_end = i;
                    break;
                }
            }
            if (line_end < 0) break;

            // Parse chunk size
            int chunk_size = parse_chunk_size(data + pos, line_end - pos);
            if (chunk_size < 0) {
                result.status_code = 400;
                return result;
            }

            // Terminal chunk
            if (chunk_size == 0) {
                result.complete = true;
                result.body = std::string(body_buffer_, static_cast<size_t>(body_length_));
                return result;
            }

            // Move past chunk size line
            pos = line_end + 2;

            // Validate chunk data availability
            // BUG: signed integer arithmetic - if pos + chunk_size overflows int,
            // the comparison becomes (negative <= data_len) which is true
            int end_of_chunk = pos + chunk_size;
            if (end_of_chunk + 2 > data_len) {
                // Not enough data yet
                break;
            }

            // Append chunk data
            if (!append_chunk(data + pos, chunk_size)) {
                result.status_code = 413;
                return result;
            }

            // Skip chunk data + CRLF
            pos = end_of_chunk + 2;
        }

        return result;
    }
};

// Integration: reverse proxy handler
class ReverseProxy {
private:
    ChunkedParser parser_;

public:
    // Process upstream response with chunked encoding
    // Called with data from upstream server socket
    std::string process_upstream_response(const std::vector<char>& raw_response) {
        if (raw_response.empty()) return "";

        // Find end of headers
        const char* data = raw_response.data();
        int total_len = static_cast<int>(std::min(raw_response.size(), 
                                                   static_cast<size_t>(INT32_MAX)));

        // Look for header/body separator
        int body_start = -1;
        for (int i = 0; i < total_len - 3; i++) {
            if (data[i] == '\r' && data[i+1] == '\n' && 
                data[i+2] == '\r' && data[i+3] == '\n') {
                body_start = i + 4;
                break;
            }
        }

        if (body_start < 0) return "";

        auto result = parser_.parse_chunked_body(data + body_start, 
                                                  total_len - body_start);
        if (result.complete) {
            return result.body;
        }
        return "";
    }
};

} // namespace http

int main() {
    // Example: process a chunked response
    http::ReverseProxy proxy;

    std::string response = "HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n";
    response += "5\r\nHello\r\n";
    response += "6\r\n World\r\n";
    response += "0\r\n\r\n";

    std::vector<char> raw(response.begin(), response.end());
    std::string body = proxy.process_upstream_response(raw);

    return 0;
}
